// ============================================================================
// ML_KEM_apb: APB4 register wrapper around ML_KEM_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/ML_KEM.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/ML_KEM.md
// ============================================================================
module ML_KEM_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq
);
  localparam logic [31:0] ID_VALUE = 32'h4D4B0101;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_start;
  logic [1:0]    c_op;
  logic [1:0]    c_pset;
  logic          c_busy;
  logic          c_done;
  logic          c_err;
  logic          c_hp_load;
  logic [10:0]   c_hp_addr;
  logic          c_hw_valid;
  logic [31:0]   c_hw_data;
  logic          c_hw_ready;
  logic          c_hr_en;
  logic          c_hr_valid;
  logic [31:0]   c_hr_data;
  logic          c_hr_ready;
  ML_KEM_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .start(c_start),
    .op(c_op),
    .pset(c_pset),
    .busy(c_busy),
    .done(c_done),
    .err(c_err),
    .hp_load(c_hp_load),
    .hp_addr(c_hp_addr),
    .hw_valid(c_hw_valid),
    .hw_data(c_hw_data),
    .hw_ready(c_hw_ready),
    .hr_en(c_hr_en),
    .hr_valid(c_hr_valid),
    .hr_data(c_hr_data),
    .hr_ready(c_hr_ready)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [4:0] r_CTRL;   // 12'h014 CTRL
  logic [10:0] r_PTR;   // 12'h018 PTR
  logic [1:0] p_CMD;   // 12'h01C CMD (pulses)
  logic [31:0] h_DATA_IN;   // 12'h020 DATA_IN holding register
  logic [31:0] h_DATA_OUT;   // 12'h024 DATA_OUT holding register
  logic full_DATA_IN;
  logic avail_DATA_OUT;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 5'h0;
      r_PTR <= 11'h0;
      p_CMD <= '0;
      h_DATA_IN <= '0;
      h_DATA_OUT <= '0;
      full_DATA_IN <= 1'b0;
      avail_DATA_OUT <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[6]) r_PTR <= (r_PTR & ~wmask[10:0]) | (PWDATA[10:0] & wmask[10:0]);
      p_CMD <= (wr && hit[7]) ? PWDATA[1:0] & wmask[1:0] : '0;
      if (wr && hit[8] && !full_DATA_IN) h_DATA_IN <= (h_DATA_IN & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8] && !full_DATA_IN) full_DATA_IN <= 1'b1;
      else if (full_DATA_IN && c_hw_ready) full_DATA_IN <= 1'b0;
      if (c_hr_valid && (!avail_DATA_OUT || (rd && hit[9]))) begin
        h_DATA_OUT[31:0] <= c_hr_data[31:0];
        avail_DATA_OUT <= 1'b1;
      end else if (rd && hit[9]) avail_DATA_OUT <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_op = r_CTRL[1:0];
  assign c_pset = r_CTRL[3:2];
  assign c_hr_en = r_CTRL[4:4];
  assign c_hp_addr = r_PTR[10:0];
  assign c_start = p_CMD[0:0];
  assign c_hp_load = p_CMD[1:1];
  assign c_hw_data[31:0] = h_DATA_IN[31:0];
  assign c_hw_valid = full_DATA_IN;
  assign c_hr_ready = ~avail_DATA_OUT | (rd & hit[9]);

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err;
    irq_set[2] = full_DATA_IN & c_hw_ready;
    irq_set[3] = wr & (hit[8]) & full_DATA_IN;
    irq_set[4] = c_hr_valid & (~avail_DATA_OUT | (rd & hit[9]));
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_DATA_OUT, full_DATA_IN};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_PTR);
      10'd8: apb_rdata = 32'(h_DATA_IN);
      10'd9: apb_rdata = 32'(h_DATA_OUT);
      10'd10: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
